const ns='http://www.w3.org/2000/svg',bridge=document.getElementById('draft-bridge');
function sync(){bridge.contentWindow?.postMessage({lootDraft:1,op:'get'},'*')}
bridge.addEventListener('load',sync);addEventListener('pageshow',sync);sync();
addEventListener('message',ev=>{
 if(ev.source!==bridge.contentWindow||ev.data?.lootDraft!==1||!ev.data.state)return;
 const flags=new Set();for(const k of Object.keys(ev.data.state)){const [kind,n]=k.split('|');if(kind==='R'){for(const node of (rarityNodes[n]||[]))flags.add(node)}else flags.add(n)}
 for(const a of document.querySelectorAll('a[href*="#"]')){
  const id=decodeURIComponent(a.getAttribute('href').split('#')[1]);const g=a.querySelector('g.node');if(!g)continue;
  let w=g.querySelector('.draft-wrench');if(!flags.has(id)){w?.remove();continue}if(w)continue;
  const b=g.getBBox();w=document.createElementNS(ns,'text');w.setAttribute('class','draft-wrench');w.setAttribute('x',b.x+b.width-11);w.setAttribute('y',b.y+6);w.setAttribute('font-size','11');w.setAttribute('pointer-events','none');w.textContent='🔧';g.append(w)
 }
})
